questionvariables.text:
/* f(A) + s*g(B) with special angles in radians. 22 expressions, chosen so that every answer is a whole number,
   a fraction or a single surd (no mixed answers such as (1+sqrt(2))/2). Each row: [f1, d1, s, f2, d2] meaning
   f1(pi/d1) + s*f2(pi/d2), with f = 1 sin, 2 cos, 3 tan. */
epool : [[1,6,1,1,2], [1,6,-1,1,2], [1,6,1,2,3], [1,6,1,3,4], [1,6,-1,3,4], [1,4,1,2,4], [1,3,1,2,6], [1,3,1,3,3],
         [1,3,-1,3,3], [1,2,-1,1,6], [1,2,1,2,3], [1,2,-1,2,3], [1,2,1,3,4], [2,6,1,3,3], [2,6,-1,3,3], [2,3,-1,1,2],
         [2,3,1,3,4], [2,3,-1,3,4], [3,4,-1,1,6], [3,4,-1,2,3], [3,3,-1,1,3], [3,3,-1,2,6]];
row : rand(epool);
f1 : row[1];
d1 : row[2];
sg : row[3];
f2 : row[4];
d2 : row[5];
A1 : %pi/d1;
A2 : %pi/d2;
dg1 : 180/d1;                  /* the angles in degrees, for the worked solution */
dg2 : 180/d2;
v1 : if f1 = 1 then (if d1 = 6 then 1/2 else if d1 = 4 then sqrt(2)/2 else if d1 = 3 then sqrt(3)/2 else 1) else if f1 = 2 then (if d1 = 6 then sqrt(3)/2 else if d1 = 4 then sqrt(2)/2 else if d1 = 3 then 1/2 else 0) else (if d1 = 6 then sqrt(3)/3 else if d1 = 4 then 1 else sqrt(3));
v2 : if f2 = 1 then (if d2 = 6 then 1/2 else if d2 = 4 then sqrt(2)/2 else if d2 = 3 then sqrt(3)/2 else 1) else if f2 = 2 then (if d2 = 6 then sqrt(3)/2 else if d2 = 4 then sqrt(2)/2 else if d2 = 3 then 1/2 else 0) else (if d2 = 6 then sqrt(3)/3 else if d2 = 4 then 1 else sqrt(3));
ta : v1 + sg*v2;
/* common slip: the value of the other ratio at the same angle (sin and cos swapped, tan inverted) */
w1 : if f1 = 1 then (if 2 = 1 then (if d1 = 6 then 1/2 else if d1 = 4 then sqrt(2)/2 else if d1 = 3 then sqrt(3)/2 else 1) else if 2 = 2 then (if d1 = 6 then sqrt(3)/2 else if d1 = 4 then sqrt(2)/2 else if d1 = 3 then 1/2 else 0) else (if d1 = 6 then sqrt(3)/3 else if d1 = 4 then 1 else sqrt(3))) else if f1 = 2 then (if 1 = 1 then (if d1 = 6 then 1/2 else if d1 = 4 then sqrt(2)/2 else if d1 = 3 then sqrt(3)/2 else 1) else if 1 = 2 then (if d1 = 6 then sqrt(3)/2 else if d1 = 4 then sqrt(2)/2 else if d1 = 3 then 1/2 else 0) else (if d1 = 6 then sqrt(3)/3 else if d1 = 4 then 1 else sqrt(3))) else 1/v1;
w2 : if f2 = 1 then (if 2 = 1 then (if d2 = 6 then 1/2 else if d2 = 4 then sqrt(2)/2 else if d2 = 3 then sqrt(3)/2 else 1) else if 2 = 2 then (if d2 = 6 then sqrt(3)/2 else if d2 = 4 then sqrt(2)/2 else if d2 = 3 then 1/2 else 0) else (if d2 = 6 then sqrt(3)/3 else if d2 = 4 then 1 else sqrt(3))) else if f2 = 2 then (if 1 = 1 then (if d2 = 6 then 1/2 else if d2 = 4 then sqrt(2)/2 else if d2 = 3 then sqrt(3)/2 else 1) else if 1 = 2 then (if d2 = 6 then sqrt(3)/2 else if d2 = 4 then sqrt(2)/2 else if d2 = 3 then 1/2 else 0) else (if d2 = 6 then sqrt(3)/3 else if d2 = 4 then 1 else sqrt(3))) else 1/v2;
twrongop : v1 - sg*v2;          /* common slip: added instead of subtracted, or the reverse */
